"use strict";

// The package's whole callable API is chosen AT RUNTIME by a resolvable
// LOCAL CALL whose own body always throws -- but, unlike RWF-016's and
// RWF-017's fixtures, the call sits in neither statement position. It is
// the initializer of a class STATIC FIELD, which JavaScript evaluates as
// part of evaluating the class DEFINITION, which is itself part of module
// evaluation. The runtime consequence is identical (see
// fixtures/commonjs-circular-import-static-field-throw-ground-truth/ for a
// real node-executed proof); only the position of the CallExpression
// differs, which is exactly what RWF-018 says must not matter.
const danger = require("./danger");

// The branch that reaches the vulnerable sink. Nothing in this file calls
// it: the ONLY way it ever runs is by being the module's exported value.
function dangerousOp(input) {
  return danger.explode(input);
}

// The branch that does not.
function safeOp(input) {
  return "safe:" + input;
}

// A resolvable local callable whose entire body is a single unconditional
// throw -- definitely abrupt by RWF-016's own model.
function bail() {
  throw new Error("fast mode is not supported here");
}

if (process.env.FIXTURE_LIB_MODE === "fast") {
  module.exports = dangerousOp;
  // Static elements run in declaration order as part of evaluating the
  // class definition, so `probe` initializes and then this necessarily
  // invokes `bail()`. It never returns, the class definition never
  // completes, `Mode` is never bound, `trailing` never initializes, and
  // module evaluation on this branch ends here.
  class Mode {
    static probe = "fast";
    static ready = bail();
    static trailing = "never initialized";
  }
}

module.exports = safeOp;
